    public IEnumerable<Expense> expense { get; set; }
    public string Message { get; set; }

    private PieConfig _config;
    private ChartJsPieChart _pieChartJs;

    protected async override Task OnInitializedAsync()
    {
        try
        {
            expense = await ExpenseService.GetAllExpenses();
        }
        catch (Exception ex)
        {
            Message = "Something went wrong" + ex.Message;
        }

        _config = new PieConfig
            {
                Options = new PieOptions
                {
                    Title = new OptionsTitle
                    {
                        Display = true,
                        Text = "Expenses"
                    },
                    Responsive = true,
                    Animation = new ArcAnimation
                    {
                        AnimateRotate = true,
                        AnimateScale = true
                    }
                }
            };

        //linQ
        _config.Data.Labels.AddRange(expense.Select(c => c.Category.Name).Distinct().ToArray());

        var pieSet = new PieDataset
            {
                BackgroundColor = new[] {ColorUtil.RandomColorString(), ColorUtil.RandomColorString(),
                                        ColorUtil.RandomColorString(), ColorUtil.RandomColorString()},
                BorderWidth = 0,
                HoverBackgroundColor = ColorUtil.RandomColorString(),
                HoverBorderColor = ColorUtil.RandomColorString(),
                HoverBorderWidth = 1,
                BorderColor = "#ffffff"

            };

            pieSet.Data.AddRange(expense
                                .GroupBy(e => e.CategoryId)
                                .Select(ec => ec.Sum(c => Convert.ToDouble(c.Amount))).ToArray());


            _config.Data.Datasets.Add(pieSet);
    }



